update public.topics set learning_overview='{"title":"Tema 1","explanation_es":"En este tema aprenderás sobre tema 1. Trabajarás el lenguaje necesario para comprenderlo y usarlo en situaciones cotidianas.","learning_outcomes":["El estudiante puede decir su nombre, pedir cómo se deletrea y confirmar una letra.","El estudiante puede identificar letras en nombres y pedir aclaración cuando no las entiende.","El estudiante puede deletrear información personal y comprobar que otra persona la registró correctamente.","El estudiante puede completar una interacción nueva que requiere deletrear, confirmar y corregir información.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":[],"vocabulary":[{"term":"clarify","meaning_es":"aclarar","example":"I need to clarify one letter."}],"pronunciation_targets":[],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=1;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=2;
update public.topics set learning_overview='{"title":"Tema 2","explanation_es":"En este tema aprenderás sobre tema 2. Trabajarás el lenguaje necesario para comprenderlo y usarlo en situaciones cotidianas.","learning_outcomes":["El estudiante puede presentarse, preguntar el nombre de otra persona y mantener un intercambio inicial.","El estudiante puede identificar a una persona o un objeto y hablar de él o ella en frases sencillas.","El estudiante puede hablar de su grupo y de otros grupos usando we y they.","El estudiante puede presentar personas, grupos y objetos usando los siete pronombres personales en una interacción nueva.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":[],"vocabulary":[{"term":"everyone","meaning_es":"todos","example":"Everyone is here."}],"pronunciation_targets":[],"lesson_count":4}'::jsonb where id=v_topic_id;
