update public.topics set learning_overview='{"title":"Tema 3","explanation_es":"En este tema aprenderás sobre tema 3. Trabajarás el lenguaje necesario para comprenderlo y usarlo en situaciones cotidianas.","learning_outcomes":["El estudiante puede decir quién es y expresar estados básicos usando I am y I''m.","El estudiante puede describir una persona o un objeto con is y explicar dónde está.","El estudiante puede describir a su interlocutor, a su propio grupo y a otros grupos usando are.","El estudiante puede describir identidad, estados y ubicación usando am, is y are en una situación nueva.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":[],"vocabulary":[{"term":"meeting","meaning_es":"reunión","example":"The meeting is ready."}],"pronunciation_targets":[],"lesson_count":4}'::jsonb where id=v_topic_id;
