update public.topics set learning_overview='{"title":"Tema 5","explanation_es":"En este tema aprenderás sobre tema 5. Trabajarás el lenguaje necesario para comprenderlo y usarlo en situaciones cotidianas.","learning_outcomes":["El estudiante puede distinguir un objeto de varios y formar plurales regulares básicos.","El estudiante puede reconocer y usar plurales frecuentes regulares e irregulares en situaciones cotidianas.","El estudiante puede formar y reconocer plurales regulares frecuentes al describir objetos cotidianos.","El estudiante puede hacer un inventario oral y escrito usando cantidades, plurales regulares e irregulares y there is/there are.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":[],"vocabulary":[{"term":"missing","meaning_es":"que falta","example":"Two chairs are missing."}],"pronunciation_targets":[],"lesson_count":4}'::jsonb where id=v_topic_id;
