update public.topics set learning_overview='{"title":"Tema 7","explanation_es":"En este tema aprenderás sobre tema 7. Trabajarás el lenguaje necesario para comprenderlo y usarlo en situaciones cotidianas.","learning_outcomes":["El estudiante puede decir qué pertenece a sí mismo o a su interlocutor usando my y your.","El estudiante puede decir a quién pertenece un objeto cuando el dueño es otra persona.","El estudiante puede identificar pertenencias de su grupo y de otros grupos usando our y their.","El estudiante puede identificar pertenencias propias, de otras personas y de grupos usando my, your, his, her, our y their.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":[],"vocabulary":[{"term":"whose","meaning_es":"de quién","example":"Whose bag is this?"}],"pronunciation_targets":[],"lesson_count":4}'::jsonb where id=v_topic_id;
