update public.topics set learning_overview='{"title":"Tema 9","explanation_es":"En este tema aprenderás sobre tema 9. Trabajarás el lenguaje necesario para comprenderlo y usarlo en situaciones cotidianas.","learning_outcomes":["El estudiante puede decir qué hay en un espacio usando there is y there are.","El estudiante puede preguntar si existe un objeto y responder afirmativa o negativamente.","El estudiante puede decir qué no hay y explicar qué falta en un espacio.","El estudiante puede comprobar una habitación, describir qué hay, qué falta y qué se necesita.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":[],"vocabulary":[{"term":"ready","meaning_es":"listo / lista","example":"The room is ready."}],"pronunciation_targets":[],"lesson_count":4}'::jsonb where id=v_topic_id;
