update public.topics set learning_overview='{"title":"Tema 1","explanation_es":"En este tema aprenderás sobre tema 1. Trabajarás el lenguaje necesario para comprenderlo y usarlo en situaciones cotidianas.","learning_outcomes":["El estudiante puede construir frases afirmativas básicas con sujeto, verbo y complemento.","El estudiante puede ampliar una frase básica con información de tiempo y lugar.","El estudiante puede reorganizar y corregir frases para transmitir un mensaje claro.","El estudiante puede construir y corregir mensajes afirmativos básicos en una situación nueva.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":[],"vocabulary":[{"term":"send","meaning_es":"enviar","example":"Send the message."}],"pronunciation_targets":[],"lesson_count":4}'::jsonb where id=v_topic_id;
