update public.topics set learning_overview='{"title":"Tema 2","explanation_es":"En este tema aprenderás sobre tema 2. Trabajarás el lenguaje necesario para comprenderlo y usarlo en situaciones cotidianas.","learning_outcomes":["El estudiante puede hablar de hábitos y rutinas usando el presente simple con I, you, we y they.","El estudiante puede describir la rutina de otra persona y reconocer la terminación de tercera persona.","El estudiante puede expresar hábitos que no realiza usando don''t y doesn''t.","El estudiante puede preguntar, responder, afirmar y negar hábitos en una conversación breve.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":[],"vocabulary":[{"term":"cook","meaning_es":"cocinar","example":"We cook at home."}],"pronunciation_targets":[],"lesson_count":4}'::jsonb where id=v_topic_id;
