update public.topics set learning_overview='{"title":"Tema 3","explanation_es":"En este tema aprenderás sobre tema 3. Trabajarás el lenguaje necesario para comprenderlo y usarlo en situaciones cotidianas.","learning_outcomes":["El estudiante puede formular preguntas sobre hábitos usando do y does.","El estudiante puede responder preguntas con do/does usando respuestas cortas afirmativas y negativas.","Responder preguntas sencillas sobre hábitos y preferencias con respuestas cortas correctas.","Mantener una mini entrevista sobre rutinas usando preguntas con do/does y respuestas breves con seguimiento.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["Yes, I do.","No, I don''t.","Yes, she does.","No, she doesn''t.","Do you...?","Does he/she...?","Yes, he/she does.","No, he/she doesn''t."],"vocabulary":[{"term":"follow-up","meaning_es":"seguimiento","example":"Ask a follow-up question."},{"word":"read","meaning_es":"leer","example":"I read every night."},{"word":"watch TV","meaning_es":"ver televisión","example":"Does he watch TV?"},{"word":"go out","meaning_es":"salir","example":"We don''t go out on Mondays."},{"word":"exercise","meaning_es":"hacer ejercicio","example":"Do you exercise?"},{"word":"usually","meaning_es":"normalmente","example":"I usually read."},{"word":"short answer","meaning_es":"respuesta corta","example":"Yes, I do."},{"word":"wake up","meaning_es":"despertarse","example":"Do you wake up early?"},{"word":"work","meaning_es":"trabajar","example":"Does she work here?"},{"word":"study","meaning_es":"estudiar","example":"Do you study English?"},{"word":"like","meaning_es":"gustar","example":"Does he like music?"},{"word":"every day","meaning_es":"todos los días","example":"I study every day."}],"pronunciation_targets":[{"text":"Yes, I do.","focus":"unir I y do sin separar demasiado"},{"text":"No, she doesn''t.","focus":"marcar la contracción doesn''t"},{"text":"Do you study English every day?","focus":"reducir do you de forma natural"},{"text":"Does your brother study English too?","focus":"distinguir does y study"}],"lesson_count":4}'::jsonb where id=v_topic_id;
