update public.topics set learning_overview='{"title":"Tema 4","explanation_es":"En este tema aprenderás sobre tema 4. Trabajarás el lenguaje necesario para comprenderlo y usarlo en situaciones cotidianas.","learning_outcomes":["Formular y comprender preguntas básicas con what, where y who.","Preguntar por tiempo, razones y maneras de hacer algo usando when, why y how.","Seleccionar y formular la pregunta adecuada para obtener información concreta en una conversación.","Mantener una conversación breve haciendo y respondiendo preguntas básicas de forma natural.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["What do you...?","Where do you...?","Who does he/she...?","When do you...?","Why do you...?","How do you...?","How often...?","What do you need?","Where is it?","Who is she?","When does it open?","Why are you here?"],"vocabulary":[{"word":"name","meaning_es":"nombre","example":"What is your name?"},{"word":"live","meaning_es":"vivir","example":"Where do you live?"},{"word":"work","meaning_es":"trabajar","example":"Where do you work?"},{"word":"friend","meaning_es":"amigo","example":"Who is your friend?"},{"word":"city","meaning_es":"ciudad","example":"What city do you live in?"},{"word":"address","meaning_es":"dirección","example":"What is your address?"},{"word":"start","meaning_es":"empezar","example":"When does the class start?"},{"word":"finish","meaning_es":"terminar","example":"When do you finish work?"},{"word":"because","meaning_es":"porque","example":"I study because I need English."},{"word":"early","meaning_es":"temprano","example":"Why do you wake up early?"},{"word":"get to","meaning_es":"llegar a","example":"How do you get to work?"},{"word":"often","meaning_es":"a menudo","example":"How often do you practice?"}],"pronunciation_targets":[{"text":"What is your name?","focus":"entonación ascendente y unión what is"},{"text":"Where do you live?","focus":"reducir do you sin perder claridad"},{"text":"Who is your friend?","focus":"mantener claro el sonido /h/"},{"text":"When does the class start?","focus":"does the como grupo de palabras"},{"text":"Why do you ask?","focus":"sonido /w/ inicial de why"},{"text":"How often do you practice?","focus":"ritmo de la pregunta completa"},{"text":"Excuse me. Where is room five?","focus":"entonación amable y enlace where is"},{"text":"When does it start?","focus":"does it como unidad"}],"lesson_count":4}'::jsonb where id=v_topic_id;
