update public.topics set learning_overview='{"title":"Tema 5","explanation_es":"En este tema aprenderás sobre tema 5. Trabajarás el lenguaje necesario para comprenderlo y usarlo en situaciones cotidianas.","learning_outcomes":["Expresar hábitos y acciones que no realizas usando don''t con I, you, we y they.","Describir hábitos negativos de otras personas usando doesn''t con he, she e it.","Formular preguntas negativas y responderlas para confirmar información sobre hábitos.","Describir hábitos afirmativos y negativos de forma conectada, comprensible y personal.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["I don''t...","You don''t...","We don''t...","They don''t...","He doesn''t...","She doesn''t...","It doesn''t...","Don''t you...?","Doesn''t he/she...?","No, I don''t.","Yes, she does.","present simple affirmative and negative"],"vocabulary":[{"word":"drive","meaning_es":"conducir","example":"I don''t drive to work."},{"word":"drink coffee","meaning_es":"tomar café","example":"I don''t drink coffee."},{"word":"watch the news","meaning_es":"ver las noticias","example":"We don''t watch the news."},{"word":"work on Sundays","meaning_es":"trabajar los domingos","example":"They don''t work on Sundays."},{"word":"every morning","meaning_es":"cada mañana","example":"I exercise every morning."},{"word":"often","meaning_es":"a menudo","example":"We don''t often eat out."},{"word":"eat meat","meaning_es":"comer carne","example":"She doesn''t eat meat."},{"word":"like spicy food","meaning_es":"gustarle la comida picante","example":"He doesn''t like spicy food."},{"word":"use a car","meaning_es":"usar un automóvil","example":"She doesn''t use a car."},{"word":"sleep late","meaning_es":"dormir hasta tarde","example":"He doesn''t sleep late."},{"word":"need","meaning_es":"necesitar","example":"It doesn''t need batteries."},{"word":"usually","meaning_es":"normalmente","example":"She usually brings lunch."}],"pronunciation_targets":[{"text":"I don''t drive.","focus":"contracción don''t clara"},{"text":"We don''t work on Sundays.","focus":"ritmo de la negación"},{"text":"They don''t drink coffee either.","focus":"either al final"},{"text":"She doesn''t drive.","focus":"contracción doesn''t"},{"text":"He doesn''t eat meat.","focus":"enlace doesn''t eat"},{"text":"It doesn''t need batteries.","focus":"it y doesn''t claramente separados"},{"text":"Don''t you bring lunch?","focus":"unir don''t you y entonación"},{"text":"Doesn''t he work here?","focus":"contracción doesn''t"}],"lesson_count":4}'::jsonb where id=v_topic_id;
