update public.topics set learning_overview='{"title":"Tema 6","explanation_es":"En este tema aprenderás sobre tema 6. Trabajarás el lenguaje necesario para comprenderlo y usarlo en situaciones cotidianas.","learning_outcomes":["Describir con qué frecuencia realizas actividades cotidianas usando adverbios básicos.","Colocar correctamente los adverbios de frecuencia con verbos principales y con el verbo to be.","Combinar adverbios y expresiones de tiempo para describir con precisión la frecuencia de una actividad.","Hablar de hábitos con adverbios y expresiones de frecuencia, hacer preguntas y comparar respuestas.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["always","usually","often","sometimes","never","subject + adverb + main verb","be + adverb","adverb at the beginning/end","every day","once a week","twice a month","three times a week"],"vocabulary":[{"word":"always","meaning_es":"siempre","example":"I always eat breakfast."},{"word":"usually","meaning_es":"normalmente","example":"I usually walk to work."},{"word":"often","meaning_es":"a menudo","example":"We often study together."},{"word":"sometimes","meaning_es":"a veces","example":"She sometimes cooks."},{"word":"never","meaning_es":"nunca","example":"They never smoke."},{"word":"practice","meaning_es":"practicar","example":"I practice often."},{"word":"be late","meaning_es":"llegar tarde/estar tarde","example":"I am never late."},{"word":"be tired","meaning_es":"estar cansado","example":"She is often tired."},{"word":"arrive","meaning_es":"llegar","example":"He usually arrives at eight."},{"word":"check email","meaning_es":"revisar el correo","example":"I always check my email."},{"word":"feel","meaning_es":"sentirse","example":"They sometimes feel tired."},{"word":"on time","meaning_es":"a tiempo","example":"We are always on time."}],"pronunciation_targets":[{"text":"I always practice in the morning.","focus":"always claramente reconocible"},{"text":"I sometimes study with Ana.","focus":"sílabas de sometimes"},{"text":"I never study alone.","focus":"never y ritmo de la frase"},{"text":"She is always on time.","focus":"unir is always"},{"text":"He usually arrives at eight.","focus":"usually y la s de arrives"},{"text":"I am never late.","focus":"am never con ritmo natural"},{"text":"three times a week","focus":"th de three y unión times a"},{"text":"once a week","focus":"once claramente, sin añadir sílabas"}],"lesson_count":4}'::jsonb where id=v_topic_id;
