update public.topics set learning_overview='{"title":"Tema 7","explanation_es":"En este tema aprenderás sobre tema 7. Trabajarás el lenguaje necesario para comprenderlo y usarlo en situaciones cotidianas.","learning_outcomes":["Nombrar lugares comunes de una ciudad y decir dónde están.","Pedir indicaciones básicas para llegar a un lugar.","Preguntar cómo llegar usando autobús, tren, metro o taxi y confirmar una ruta.","Pedir, comprender y dar indicaciones completas por calles o transporte.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["There is/are","The ... is near/next to...","Where is...?","I go to the...","How do I get to...?","go straight","turn left/right","at the corner","on your left/right","How can I get to...?","Which bus/train...?","Take the..."],"vocabulary":[{"word":"bank","meaning_es":"banco","example":"The bank is near the station."},{"word":"supermarket","meaning_es":"supermercado","example":"I go to the supermarket."},{"word":"pharmacy","meaning_es":"farmacia","example":"The pharmacy is next to the bank."},{"word":"hospital","meaning_es":"hospital","example":"The hospital is on Main Street."},{"word":"library","meaning_es":"biblioteca","example":"There is a library downtown."},{"word":"park","meaning_es":"parque","example":"We walk in the park."},{"word":"go straight","meaning_es":"seguir derecho","example":"Go straight for two blocks."},{"word":"turn left","meaning_es":"girar a la izquierda","example":"Turn left at the corner."},{"word":"turn right","meaning_es":"girar a la derecha","example":"Turn right after the bank."},{"word":"corner","meaning_es":"esquina","example":"The cafe is on the corner."},{"word":"block","meaning_es":"cuadra","example":"Walk two blocks."},{"word":"crosswalk","meaning_es":"paso de peatones","example":"Use the crosswalk."}],"pronunciation_targets":[{"text":"Is there a supermarket near here?","focus":"is there y near here"},{"text":"The pharmacy is next to the bank.","focus":"pharmacy y next to"},{"text":"It is across from the park.","focus":"across from"},{"text":"How do I get to the train station?","focus":"how do I get to"},{"text":"Go straight for two blocks.","focus":"straight y blocks"},{"text":"Turn right at the bank.","focus":"turn right"},{"text":"How can I get to the museum?","focus":"how can I get to"},{"text":"Take the number five bus.","focus":"number five bus"}],"lesson_count":4}'::jsonb where id=v_topic_id;
