update public.topics set learning_overview='{"title":"Tema 8","explanation_es":"En este tema aprenderás sobre tema 8. Trabajarás el lenguaje necesario para comprenderlo y usarlo en situaciones cotidianas.","learning_outcomes":["Hablar de un viaje básico, destino, transporte y equipaje.","Pedir información y seguir instrucciones básicas en una estación o aeropuerto.","Hacer check-in, confirmar una reserva y pedir información básica en un hotel.","Explicar una necesidad o problema básico y pedir ayuda durante un viaje.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["I am going to...","I am traveling by...","I have...","Where are you going?","When are you leaving?","Where is...?","Which platform/gate...?","What time does it leave?","I need...","Is this...?","I have a reservation","My name is..."],"vocabulary":[{"word":"trip","meaning_es":"viaje","example":"I am planning a trip."},{"word":"destination","meaning_es":"destino","example":"My destination is Boston."},{"word":"flight","meaning_es":"vuelo","example":"My flight is at ten."},{"word":"train","meaning_es":"tren","example":"I am traveling by train."},{"word":"suitcase","meaning_es":"maleta","example":"My suitcase is small."},{"word":"passport","meaning_es":"pasaporte","example":"I have my passport."},{"word":"departure","meaning_es":"salida","example":"The departure is at ten."},{"word":"arrival","meaning_es":"llegada","example":"What time is the arrival?"},{"word":"platform","meaning_es":"andén","example":"The train leaves from platform three."},{"word":"gate","meaning_es":"puerta de embarque","example":"Where is gate five?"},{"word":"ticket","meaning_es":"billete/boleto","example":"I need a ticket to Boston."},{"word":"luggage","meaning_es":"equipaje","example":"Where can I leave my luggage?"}],"pronunciation_targets":[{"text":"I am going to Boston.","focus":"going to Boston"},{"text":"I am traveling by train.","focus":"traveling by train"},{"text":"I am leaving on Friday morning.","focus":"leaving on Friday"},{"text":"Where is platform three?","focus":"platform three"},{"text":"What time does the train leave?","focus":"does the train leave"},{"text":"Do I need a ticket?","focus":"do I need"},{"text":"I have a reservation.","focus":"have a reservation"},{"text":"What floor is my room on?","focus":"floor y room on"}],"lesson_count":4}'::jsonb where id=v_topic_id;
