update public.topics set learning_overview='{"title":"Tema 9","explanation_es":"En este tema aprenderás sobre tema 9. Trabajarás el lenguaje necesario para comprenderlo y usarlo en situaciones cotidianas.","learning_outcomes":["Decir a qué te dedicas, dónde trabajas y qué haces durante el día.","Describir qué estudias, dónde y cuándo tienes clases.","Hablar de tareas simples, pedir ayuda y coordinar actividades con compañeros.","Describir tu trabajo o estudios, rutina, tareas y objetivos básicos.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["What do you do?","I am a...","I work as...","I work in/at...","I like my job","I study...","I am taking a course","I have class on...","I study at...","What are you studying?","I need to...","I have to..."],"vocabulary":[{"word":"job","meaning_es":"trabajo/empleo","example":"I like my job."},{"word":"office","meaning_es":"oficina","example":"I work in an office."},{"word":"store","meaning_es":"tienda","example":"She works at a store."},{"word":"teacher","meaning_es":"profesor/a","example":"My teacher is kind."},{"word":"nurse","meaning_es":"enfermero/a","example":"She works as a nurse."},{"word":"engineer","meaning_es":"ingeniero/a","example":"I am an engineer."},{"word":"course","meaning_es":"curso","example":"I am taking an English course."},{"word":"class","meaning_es":"clase","example":"I have class on Tuesday."},{"word":"subject","meaning_es":"materia","example":"English is my favorite subject."},{"word":"student","meaning_es":"estudiante","example":"I am a student."},{"word":"homework","meaning_es":"tarea","example":"I do my homework at night."},{"word":"task","meaning_es":"tarea","example":"I have a task for today."}],"pronunciation_targets":[{"text":"What do you do?","focus":"pregunta fija de profesión"},{"text":"I work as an engineer.","focus":"work as an engineer"},{"text":"I work at a school.","focus":"work at a school"},{"text":"I am taking an English course.","focus":"taking an English course"},{"text":"I have class on Tuesday and Thursday.","focus":"days and class"},{"text":"I do my homework at night.","focus":"do my homework"},{"text":"What are you working on?","focus":"working on"},{"text":"Can you send me the file?","focus":"send me the file"}],"lesson_count":4}'::jsonb where id=v_topic_id;
