update public.topics set learning_overview='{"title":"Tema 10","explanation_es":"En este tema aprenderás sobre tema 10. Trabajarás el lenguaje necesario para comprenderlo y usarlo en situaciones cotidianas.","learning_outcomes":["Pedir ayuda y explicar una necesidad básica con cortesía.","Expresar necesidades relacionadas con comida, salud, transporte y comunicación.","Comunicar un problema básico, describir una necesidad urgente y pedir la ayuda adecuada.","Usar inglés funcional para pedir ayuda, explicar necesidades y resolver una situación cotidiana completa.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["Excuse me","Can you help me?","Could you help me?","I need help with...","Where can I...?","Thank you","I need...","I need to...","I don''t have...","Can I...?","Do you have...?","Here you are"],"vocabulary":[{"word":"help","meaning_es":"ayuda/ayudar","example":"Can you help me?"},{"word":"find","meaning_es":"encontrar","example":"I need help finding my bag."},{"word":"understand","meaning_es":"entender","example":"I understand now."},{"word":"information","meaning_es":"información","example":"I need some information."},{"word":"explain","meaning_es":"explicar","example":"Let me explain the problem."},{"word":"problem","meaning_es":"problema","example":"I have a problem."},{"word":"water","meaning_es":"agua","example":"I need some water."},{"word":"medicine","meaning_es":"medicina","example":"I need medicine."},{"word":"phone charger","meaning_es":"cargador de teléfono","example":"Do you have a phone charger?"},{"word":"ticket","meaning_es":"billete/entrada","example":"I need a ticket."},{"word":"restroom","meaning_es":"baño","example":"Where is the restroom?"},{"word":"urgent","meaning_es":"urgente","example":"This is urgent."}],"pronunciation_targets":[{"text":"Excuse me. Can you help me?","focus":"excuse me y help me"},{"text":"I need some information.","focus":"need some information"},{"text":"Thank you for your help.","focus":"thank you for your help"},{"text":"I need a ticket to Boston.","focus":"need a ticket to"},{"text":"I also need a phone charger.","focus":"phone charger"},{"text":"Can I pay by card?","focus":"pay by card"},{"text":"I am lost. I need help.","focus":"lost y need help"},{"text":"My phone is broken.","focus":"phone is broken"}],"lesson_count":4}'::jsonb where id=v_topic_id;
